        "\tmov.b64 {f15_y7,f15_y8}, f15_o3;\n"
        "\tmov.b64 {f15_y9,f15_y10}, f15_o4;\n"
        "\tmov.b64 {f15_y11,f15_y12}, f15_o5;\n"
        "\tmov.b64 {f15_y13,f15_y14}, f15_o6;\n"
        "\tadd.cc.u32 f15_x1, f15_x1, f15_y1;\n"
        "\taddc.cc.u32 f15_x2, f15_x2, f15_y2;\n"
        "\taddc.cc.u32 f15_x3, f15_x3, f15_y3;\n"
        "\taddc.cc.u32 f15_x4, f15_x4, f15_y4;\n"
        "\taddc.cc.u32 f15_x5, f15_x5, f15_y5;\n"
        "\taddc.cc.u32 f15_x6, f15_x6, f15_y6;\n"
        "\taddc.cc.u32 f15_x7, f15_x7, f15_y7;\n"
        "\taddc.cc.u32 f15_x8, f15_x8, f15_y8;\n"
        "\taddc.cc.u32 f15_x9, f15_x9, f15_y9;\n"
        "\taddc.cc.u32 f15_x10, f15_x10, f15_y10;\n"
        "\taddc.cc.u32 f15_x11, f15_x11, f15_y11;\n"
        "\taddc.cc.u32 f15_x12, f15_x12, f15_y12;\n"
        "\taddc.cc.u32 f15_x13, f15_x13, f15_y13;\n"
        "\taddc.cc.u32 f15_x14, f15_x14, f15_y14;\n"
        "\taddc.u32 f15_x15, f15_x15, f15_o15;\n"
        "\t.reg .u64 f15_r0,f15_r1,f15_r2,f15_r3,f15_h0,f15_h1,f15_h2,f15_h3,f15_f0,f15_f1,f15_f2,f15_f3,f15_g0,f15_g1,f15_g2,f15_g3;\n"
        "\t.reg .u32 f15_f8,f15_g8,f15_z0,f15_z1,f15_z2,f15_z3,f15_z4,f15_z5,f15_z6,f15_z7,f15_z8,f15_z9,f15_w0,f15_w1,f15_w2,f15_w3,f15_w4,f15_w5,f15_w6,f15_w7,f15_m0,f15_m1,f15_m2;\n"
        "\tmov.b64 f15_r0, {f15_x0,f15_x1}; mov.b64 f15_r1, {f15_x2,f15_x3}; mov.b64 f15_r2, {f15_x4,f15_x5}; mov.b64 f15_r3, {f15_x6,f15_x7};\n"
        "\tmov.b64 f15_h0, {f15_x8,f15_x9}; mov.b64 f15_h1, {f15_x10,f15_x11}; mov.b64 f15_h2, {f15_x12,f15_x13}; mov.b64 f15_h3, {f15_x14,f15_x15};\n"
        "\tmul.wide.u32 f15_t, f15_x8, 977;  add.cc.u64  f15_f0, f15_r0, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x10, 977; addc.cc.u64 f15_f1, f15_r1, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x12, 977; addc.cc.u64 f15_f2, f15_r2, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x14, 977; addc.cc.u64 f15_f3, f15_r3, f15_t;\n"
        "\taddc.u32 f15_f8, 0, 0;\n"
        "\tmul.wide.u32 f15_t, f15_x9, 977;  add.cc.u64  f15_g0, f15_h0, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x11, 977; addc.cc.u64 f15_g1, f15_h1, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x13, 977; addc.cc.u64 f15_g2, f15_h2, f15_t;\n"
        "\tmul.wide.u32 f15_t, f15_x15, 977; addc.u64 f15_g3, f15_h3, f15_t;\n"
        "\tmov.b64 {f15_z0,f15_z1}, f15_f0;\n"
        "\tmov.b64 {f15_z2,f15_z3}, f15_f1;\n"
        "\tmov.b64 {f15_z4,f15_z5}, f15_f2;\n"
        "\tmov.b64 {f15_z6,f15_z7}, f15_f3;\n"
        "\tmov.b64 {f15_w0,f15_w1}, f15_g0;\n"
        "\tmov.b64 {f15_w2,f15_w3}, f15_g1;\n"
        "\tmov.b64 {f15_w4,f15_w5}, f15_g2;\n"
        "\tmov.b64 {f15_w6,f15_w7}, f15_g3;\n"
        "\tadd.cc.u32  f15_z1, f15_z1, f15_w0;\n"
        "\taddc.cc.u32 f15_z2, f15_z2, f15_w1;\n"
        "\taddc.cc.u32 f15_z3, f15_z3, f15_w2;\n"
        "\taddc.cc.u32 f15_z4, f15_z4, f15_w3;\n"
        "\taddc.cc.u32 f15_z5, f15_z5, f15_w4;\n"
        "\taddc.cc.u32 f15_z6, f15_z6, f15_w5;\n"
        "\taddc.cc.u32 f15_z7, f15_z7, f15_w6;\n"
        "\taddc.u32 f15_z8, f15_f8, f15_w7;\n"
        "\t{ .reg .u64 f15_sfz,f15_sft; .reg .u32 f15_sfl;\n\tmov.b64 f15_sfz, {f15_z0, f15_z8};\n\tmul.wide.u32 f15_sft, f15_z8, 977; add.cc.u64 f15_sft, f15_sft, f15_sfz;\n\taddc.u32 f15_m2, 0, 0;\n\tmov.b64 {f15_z0, f15_sfl}, f15_sft;\n\tadd.cc.u32 f15_z1, f15_z1, f15_sfl; }\n\t "
#if QSB_SHORT_CARRY2
        "addc.u32 f15_z2, f15_z2, f15_m2;"
#if QSB_SHORT_CARRY2_SENTINEL
        "xor.b32 f15_z0,f15_z0,0xC0DE000B;\n\t"
#endif
#else
        "addc.cc.u32 f15_z2, f15_z2, f15_m2;\n"
        "\taddc.cc.u32 f15_z3, f15_z3, 0;\n"
        "\taddc.u32 f15_z4, f15_z4, 0;"
#endif
        "\n"
        "\tmov.b64 Q0, {f15_z0,f15_z1}; mov.b64 Q1, {f15_z2,f15_z3}; mov.b64 Q2, {f15_z4,f15_z5}; mov.b64 Q3, {f15_z6,f15_z7};\n"
#endif
        "\t\n"
        "mov.u64 %0,T0;\n"
        "mov.u64 %1,T1;\n"
        "mov.u64 %2,T2;\n"
        "mov.u64 %3,T3;\n"
        "mov.u64 %4,Q0;\n"
        "mov.u64 %5,Q1;\n"
        "mov.u64 %6,Q2;\n"
        "mov.u64 %7,Q3;\n"
        "mov.u64 %8,ZZ0;\n"
        "mov.u64 %9,ZZ1;\n"
        "mov.u64 %10,ZZ2;\n"
        "mov.u64 %11,ZZ3;\n"
        "mov.u64 %12,ZZZ0;\n"
        "mov.u64 %13,ZZZ1;\n"
        "mov.u64 %14,ZZZ2;\n"
        "mov.u64 %15,ZZZ3;\n"
        "mov.u32 %16,0;\n"
#if QSB_CHAIN_ANCHOR_UPDATE
        "mov.u64 %17,AY0;\n"
        "mov.u64 %18,AY1;\n"
        "mov.u64 %19,AY2;\n"
        "mov.u64 %20,AY3;\n"
#endif
        "}\n"
#if QSB_CHAIN_ANCHOR_UPDATE
        : "+l"(X1[0]), "+l"(X1[1]), "+l"(X1[2]), "+l"(X1[3]), "+l"(Y1[0]), "+l"(Y1[1]), "+l"(Y1[2]), "+l"(Y1[3]), "+l"(ZZ1[0]), "+l"(ZZ1[1]), "+l"(ZZ1[2]), "+l"(ZZ1[3]), "+l"(ZZZ1[0]), "+l"(ZZZ1[1]), "+l"(ZZZ1[2]), "+l"(ZZZ1[3]), "+r"(bad), "+l"(Yoff[0]), "+l"(Yoff[1]), "+l"(Yoff[2]), "+l"(Yoff[3])
        : "l"(X2[0]), "l"(X2[1]), "l"(X2[2]), "l"(X2[3]), "l"(Y2[0]), "l"(Y2[1]), "l"(Y2[2]), "l"(Y2[3]));
#else
        : "+l"(X1[0]), "+l"(X1[1]), "+l"(X1[2]), "+l"(X1[3]), "+l"(Y1[0]), "+l"(Y1[1]), "+l"(Y1[2]), "+l"(Y1[3]), "+l"(ZZ1[0]), "+l"(ZZ1[1]), "+l"(ZZ1[2]), "+l"(ZZ1[3]), "+l"(ZZZ1[0]), "+l"(ZZZ1[1]), "+l"(ZZZ1[2]), "+l"(ZZZ1[3]), "+r"(bad)
        : "l"(X2[0]), "l"(X2[1]), "l"(X2[2]), "l"(X2[3]), "l"(Y2[0]), "l"(Y2[1]), "l"(Y2[2]), "l"(Y2[3]), "l"(Yoff[0]), "l"(Yoff[1]), "l"(Yoff[2]), "l"(Yoff[3]));
#endif
    return;
  }
#endif

  uint64_t U2[4];
  uint64_t S2[4];
  uint64_t P[4];
  uint64_t R[4];
  uint64_t PP[4];
  uint64_t PPP[4];
  uint64_t Q[4];
  uint64_t T[4];

  qsb_filter_mul(U2, (uint64_t *)X2, ZZ1,bad);   // U2 = X2*ZZ1
  qsb_filter_add(S2, (uint64_t *)Y2, (uint64_t *)Yoff,bad);
  qsb_filter_mul(S2, ZZZ1,bad);                  // S2 = (Y2+Yoff)*ZZZ1
  _ModSub256(P, U2, X1);               // P  = U2 - X1
  _ModSub256(R, S2, Y1);               // R  = S2 - Y1
  qsb_filter_sqr(PP, P,bad);                      // PP = P^2
  qsb_filter_mul(PPP, PP, P,bad);                // PPP = P*PP
  qsb_filter_mul(Q, U2, PP,bad);                 // V  = U2*PP
  qsb_filter_mul(ZZ1, PP,bad);                   // ZZ3; PP dies before the R^2/Y3 tail

  qsb_filter_sqr(T, R,bad);                       // R^2
  qsb_filter_add(T, T, PPP,bad);
  _ModSub256(T, T, Q);
  _ModSub256(T, T, Q);                 // X3 = R^2 + PPP - 2V

  qsb_filter_mul(ZZZ1, PPP,bad);                 // ZZZ3
  _ModSub256(Q, Q, T);                 // V - X3
  qsb_filter_mul(Q, R,bad);                      // R*(V - X3)
  if (DEFER_Y) {
    Load256(Y1, Q);                    // actual Y3 = Y1 - Y2*ZZZ3
  } else {
    qsb_filter_mul(S2, (uint64_t *)Y2, ZZZ1,bad);// affine Y2*ZZZ3
    _ModSub256(Y1, Q, S2);             // exact Y3
  }

  Load256(X1, T);                      // X3
}

// The seed-X3 opportunity is independently identified in fkiene PR338,
// e532114a2b3bc9a86ef618238ee77631cbe15924. This implementation uses our
// signed-quotient fold from ad4b6d1, with a retained boundary guard and the
// unchanged exact whole-chain replay. Preserve all prior notices and licenses.
__device__ __forceinline__ void qsb_filter_seed_x3(
    uint64_t *r,const uint64_t *a,const uint64_t *b,const uint64_t *c,uint32_t &bad){
#ifdef __CUDA_ARCH__
    uint64_t r0,r1,r2,r3,high;
    // a-b-2c = low+h*2^256, h in {-3,-2,-1,0}, for all 256-bit inputs.
    // low+h*K lies in (-3K,2^256). A boundary flag triggers exact chain replay.
    asm("{\n\t.reg .u64 h,t,ext;\n\t"
        "sub.cc.u64 %0,%5,%9;\n\t"
        "subc.cc.u64 %1,%6,%10;\n\t"
        "subc.cc.u64 %2,%7,%11;\n\t"
        "subc.cc.u64 %3,%8,%12;\n\t"
        "subc.u64 h,0,0;\n\t"
        "sub.cc.u64 %0,%0,%13;\n\t"
        "subc.cc.u64 %1,%1,%14;\n\t"
        "subc.cc.u64 %2,%2,%15;\n\t"
        "subc.cc.u64 %3,%3,%16;\n\t"
        "subc.u64 h,h,0;\n\t"
        "sub.cc.u64 %0,%0,%13;\n\t"
        "subc.cc.u64 %1,%1,%14;\n\t"
        "subc.cc.u64 %2,%2,%15;\n\t"
        "subc.cc.u64 %3,%3,%16;\n\t"
        "subc.u64 h,h,0;\n\t"
        "shr.s64 ext,h,63;\n\t"
        "mul.lo.u64 t,h,0x1000003d1;\n\t"
        "add.cc.u64 %0,%0,t;\n\t"
        ""
#if QSB_SHORT_CARRY2
        "addc.u64 %1,%1,ext; mov.u64 %4,0;"
#if QSB_SHORT_CARRY2_SENTINEL
        "xor.b64 %0,%0,0xC0DE000D;\n\t"
#endif
#else
        "addc.cc.u64 %1,%1,ext;\n\t"
        "addc.cc.u64 %2,%2,ext;\n\t"
        "addc.cc.u64 %3,%3,ext;\n\t"
        "addc.u64 %4,ext,0;"
#endif
        "\n\t}"
        : "=l"(r0),"=l"(r1),"=l"(r2),"=l"(r3),"=l"(high)
        : "l"(a[0]),"l"(a[1]),"l"(a[2]),"l"(a[3]),
          "l"(b[0]),"l"(b[1]),"l"(b[2]),"l"(b[3]),
          "l"(c[0]),"l"(c[1]),"l"(c[2]),"l"(c[3]));

    r[0]=r0;r[1]=r1;r[2]=r2;r[3]=r3;
#else
    _ModSub256(r,(uint64_t*)a,(uint64_t*)b);
    _ModSub256(r,r,(uint64_t*)c);_ModSub256(r,r,(uint64_t*)c);

#endif
}

__device__ void qsb_filter_point_seed(uint64_t *X3, uint64_t *Y3, uint64_t *ZZ3, uint64_t *ZZZ3,
                                     const uint64_t *X1, const uint64_t *Y1,
                                     const uint64_t *X2, const uint64_t *Y2, uint32_t &bad)
{
  uint64_t P[4];
  uint64_t R[4];
  uint64_t Q[4];
  uint64_t T[4];

  _ModSub256(P, (uint64_t *)X2, (uint64_t *)X1);   // P = X2 - X1
  _ModSub256(R, (uint64_t *)Y2, (uint64_t *)Y1);   // R = Y2 - Y1
  qsb_filter_sqr(ZZ3, P,bad);                                 // ZZ3  = PP  = P^2
  qsb_filter_mul(ZZZ3, ZZ3, P,bad);                          // ZZZ3 = PPP = P*PP
  qsb_filter_mul(Q, (uint64_t *)X1, ZZ3,bad);                // Q = X1*PP

  qsb_filter_sqr(T, R,bad);                                   // R^2
  qsb_filter_seed_x3(T,T,ZZZ3,Q,bad); // guarded R^2 - PPP - 2Q

  _ModSub256(Q, Q, T);                             // Q - X3
  qsb_filter_mul(Y3, Q, R,bad);                              // deferred R*(Q-X3)
  Load256(X3, T);                                  // X3
}
